package ro.leo.visual;
import android.app.DownloadManager;import android.bluetooth.*;import android.content.*;import android.database.Cursor;import android.net.*;import android.net.wifi.*;import android.os.Bundle;import java.util.*;
/** Read-only overview. No discovery, tethering change or device disconnect on entry. */
public final class ConnectionDashboardActivity extends LeoActivity {
 private BluetoothAdapter adapter;private final HashMap<Integer,BluetoothProfile> profiles=new HashMap<Integer,BluetoothProfile>();private boolean registered,visible,loading,closed,refreshAgain;private int selected;
 private final BluetoothProfile.ServiceListener listener=new BluetoothProfile.ServiceListener(){public void onServiceConnected(int id,BluetoothProfile p){if(closed){if(adapter!=null)adapter.closeProfileProxy(id,p);return;}profiles.put(id,p);show();}public void onServiceDisconnected(int id){profiles.remove(id);show();}};
 private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){show();}};
 protected void onCreate(Bundle b){super.onCreate(b);adapter=BluetoothAdapter.getDefaultAdapter();if(adapter!=null)for(int id:new int[]{BluetoothProfile.A2DP,BluetoothProfile.HEADSET,4})adapter.getProfileProxy(this,listener,id);}
 protected void onResume(){super.onResume();visible=true;IntentFilter f=new IntentFilter(WifiManager.NETWORK_STATE_CHANGED_ACTION);f.addAction(BluetoothAdapter.ACTION_CONNECTION_STATE_CHANGED);f.addAction("android.bluetooth.a2dp.profile.action.CONNECTION_STATE_CHANGED");f.addAction("android.bluetooth.input.profile.action.CONNECTION_STATE_CHANGED");f.addAction("android.net.wifi.WIFI_AP_STATE_CHANGED");f.addAction(DownloadManager.ACTION_DOWNLOAD_COMPLETE);registerReceiver(updates,f);registered=true;show();}
 protected void onPause(){visible=false;if(registered)unregisterReceiver(updates);registered=false;super.onPause();}
 protected void onDestroy(){closed=true;if(adapter!=null)for(Map.Entry<Integer,BluetoothProfile> p:profiles.entrySet())adapter.closeProfileProxy(p.getKey(),p.getValue());super.onDestroy();}
 private String hotspot(WifiManager wifi){try{int s=(Integer)WifiManager.class.getMethod("getWifiApState").invoke(wifi);return s==13?"Pornit":s==12?"Se pornește":s==10?"Se oprește":s==14?"Eroare":"Oprit";}catch(Exception e){return "Necunoscut";}}
 private String usb(){try{return (String)Class.forName("android.os.SystemProperties").getMethod("get",String.class,String.class).invoke(null,"sys.leo.usb.state","necunoscut");}catch(Exception e){return "necunoscut";}}
 private void show(){if(!visible)return;if(loading){refreshAgain=true;return;}loading=true;final ArrayList<String> rows=new ArrayList<String>();try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkInfo active=cm.getActiveNetworkInfo();rows.add("Internet · "+(active!=null&&active.isConnected()?active.getTypeName():"Fără conexiune"));WifiManager wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);WifiInfo info=wifi.getConnectionInfo();rows.add("Wi-Fi · "+(wifi.isWifiEnabled()?info!=null&&info.getNetworkId()>=0?info.getSSID()+" · "+info.getRssi()+" dBm":"Pornit · neconectat":"Oprit"));rows.add("Hotspot · "+hotspot(wifi)+"\nLista clienților nu este raportată de acest API");StringBuilder devices=new StringBuilder();Set<String> seen=new HashSet<String>();for(Map.Entry<Integer,BluetoothProfile> profile:profiles.entrySet())for(BluetoothDevice d:profile.getValue().getConnectedDevices()){String label=(d.getName()==null?"Dispozitiv":d.getName())+" · "+(profile.getKey()==BluetoothProfile.A2DP?"audio A2DP":profile.getKey()==4?"HID":"apeluri");if(seen.add(label)){if(devices.length()>0)devices.append('\n');devices.append(label);}}rows.add("Bluetooth · "+(adapter==null?"Indisponibil":!adapter.isEnabled()?"Oprit":devices.length()==0?"Niciun profil conectat":devices));rows.add("USB · "+usb());long rx=TrafficStats.getTotalRxBytes(),tx=TrafficStats.getTotalTxBytes();rows.add("Trafic de la pornire\n"+(rx<0||tx<0?"Indisponibil":android.text.format.Formatter.formatFileSize(this,rx)+" primit · "+android.text.format.Formatter.formatFileSize(this,tx)+" trimis"));}catch(RuntimeException e){rows.add("Unele servicii nu pot fi citite");}
  worker.execute(new Runnable(){public void run(){int running=0,waiting=0,failed=0;try{DownloadManager dm=(DownloadManager)getSystemService(DOWNLOAD_SERVICE);try(Cursor c=dm.query(new DownloadManager.Query())){int n=0;while(c!=null&&c.moveToNext()&&n++<300){int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_RUNNING)running++;else if(status==DownloadManager.STATUS_PENDING||status==DownloadManager.STATUS_PAUSED)waiting++;else if(status==DownloadManager.STATUS_FAILED)failed++;}}}catch(RuntimeException e){}rows.add("Descărcări · "+running+" active · "+waiting+" în așteptare · "+failed+" erori");ui(new Runnable(){public void run(){loading=false;if(!visible)return;if(refreshAgain){refreshAgain=false;show();return;}list("Conexiuni Leo",rows,selected,new Choice(){public void pick(int n){selected=n;String chosen=rows.get(n);if(chosen.startsWith("Wi-Fi")||chosen.startsWith("Hotspot"))startActivity(new Intent(ConnectionDashboardActivity.this,ConnectivityActivity.class).putExtra("kind",chosen.startsWith("Wi-Fi")?"wifi":"hotspot"));else if(chosen.startsWith("Bluetooth"))startActivity(new Intent(ConnectionDashboardActivity.this,ConnectivityActivity.class).putExtra("kind","bluetooth"));else if(chosen.startsWith("USB"))startActivity(new Intent(ConnectionDashboardActivity.this,UsbTransferActivity.class));else if(chosen.startsWith("Descărcări"))startActivity(new Intent(ConnectionDashboardActivity.this,DownloadsActivity.class));}},"Actualizează",new Runnable(){public void run(){show();}});}});}});
 }
 void onListSelection(String title,int at){selected=at;}
}
